(experiments
 .filter(pl.col('Experiment') == 'Welcome tutorial')
 .join(actions.filter(pl.col('Action') == 'Tutorial complete'),
       on='User_ID',
       how='left')
 .group_by('Variant')
 .agg(Total_Cohorted=pl.col('User_ID').count(),
      Completions=pl.col('Action').is_not_null().sum())
 .with_columns(Pct_Completed=pl.col('Completions') / pl.col('Total_Cohorted'))
)
```

