 .join(payments, on='User_ID', how='left')
 .group_by('Variant', 'User_ID')
 .agg(Amount=pl.col('Amount').fill_null(0).sum())
 .group_by('Variant')
 .agg(Total_Cohorted=pl.col('User_ID').count(),
      Buyers=pl.col('Amount').filter(pl.col('Amount') > 0).count(),
      Pct_Buyers=pl.col('Amount').filter(pl.col('Amount') > 0).count() / pl.col('User_ID').count())
